def gui_inert_script():
 # Actual full child wrapper decompression/hash executes, then replaces ONLY its final invocation.
 child=m.bodies()[1];tail='&([ScriptBlock]::Create([Text.Encoding]::UTF8.GetString($vr,0,$vs)))'
 if child.count(tail)!=1:raise ValueError('gui-inert-loader-boundary')
 loader=child.replace(tail,"$completeSource=[Text.Encoding]::UTF8.GetString($vr,0,$vs)")
 packed=re.search(r"FromBase64String\('([^']+)'\)",child).group(1);plain=gzip.decompress(base64.b64decode(packed)).decode()
 start=plain.index("'UIAutomationClient','UIAutomationTypes','WindowsBase'");stop=plain.index('$cf=[CP117InputRead]::Read',start);compiler=plain[start:stop]
 marker='Add-Type -ReferencedAssemblies '
 if compiler.count(marker)!=1 or '::Read('in compiler:raise ValueError('gui-inert-compiler-boundary')
 compiler=compiler.replace(marker,"$c+=@'\n"+_ROLE_FAKE_CS+"\n'@\n"+marker)
 # Forged hash and expansion bounds exercise the actual loader before any invocation.
 digest=hashlib.sha256(plain.encode()).hexdigest();old=loader.replace(digest,'0'*64)
 expectedLength=re.search(r"if\(\$vs -ne (\d+) \)",loader).group(1);oversize=loader.replace('$vs -ne '+expectedLength+' ', '$vs -ne 1 ')
 return "$ErrorActionPreference='Stop';\n$forged=$false;try{&([ScriptBlock]::Create([Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('"+base64.b64encode(old.encode()).decode()+"'))))}catch{if($_.Exception.Message -cne 'ROLE_FULL_BODY_HASH'){throw};$forged=$true}\n$bound=$false;try{&([ScriptBlock]::Create([Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('"+base64.b64encode(oversize.encode()).decode()+"'))))}catch{if($_.Exception.Message -cne 'ROLE_FULL_BODY_BOUND'){throw};$bound=$true}\n"+loader+compiler+"\nif(-not $forged -or -not $bound -or -not [GuiRoleFixture]::Run()){throw 'GUI_ROLE_INERT_CASES'};[Console]::Out.WriteLine('GUI_ROLE_CASES_PASS')\n"

